const crypto=require('crypto');
const fs=require('fs');
const path=require('path');
const zlib=require('zlib');

function sha256(value){return crypto.createHash('sha256').update(value).digest('hex')}
function safePath(value){const path=String(value||'').replaceAll('\\','/');if(!path||path.startsWith('/')||path.split('/').some(part=>!part||part==='.'||part==='..'))throw Object.assign(new Error('Releasepfad ist unsicher.'),{code:'RELEASE_PATH_INVALID'});if(Buffer.byteLength(path)>100)throw Object.assign(new Error('Releasepfad überschreitet das portable Tar-Limit.'),{code:'RELEASE_PATH_TOO_LONG'});return path}
function octal(value,width){const text=Math.max(0,Number(value)).toString(8);if(text.length>width-1)throw new Error('Tar-Wert ist zu groß.');return `${text.padStart(width-1,'0')}\0`}
function writeText(buffer,offset,length,value){Buffer.from(String(value)).copy(buffer,offset,0,length)}
function tarHeader({path,size,mode=0o644,mtime=0}){const header=Buffer.alloc(512);writeText(header,0,100,safePath(path));writeText(header,100,8,octal(mode,8));writeText(header,108,8,octal(0,8));writeText(header,116,8,octal(0,8));writeText(header,124,12,octal(size,12));writeText(header,136,12,octal(mtime,12));header.fill(0x20,148,156);header[156]=0x30;writeText(header,257,6,'ustar\0');writeText(header,263,2,'00');writeText(header,265,32,'root');writeText(header,297,32,'root');const checksum=header.reduce((sum,byte)=>sum+byte,0);writeText(header,148,8,`${checksum.toString(8).padStart(6,'0')}\0 `);return header}
function createTar(entries,{mtime=0}={}){const chunks=[];for(const entry of [...entries].sort((a,b)=>a.path.localeCompare(b.path,'en'))){const content=Buffer.isBuffer(entry.content)?entry.content:Buffer.from(entry.content);chunks.push(tarHeader({path:entry.path,size:content.length,mode:entry.mode,mtime}),content);const padding=(512-content.length%512)%512;if(padding)chunks.push(Buffer.alloc(padding))}chunks.push(Buffer.alloc(1024));return Buffer.concat(chunks)}
function createManifest(entries,{name,version,target='systemone-pi',sourceCommit,sourceTimestamp}){if(!/^[a-f0-9]{40}$/.test(String(sourceCommit||'')))throw Object.assign(new Error('Vollständiger Git-Commit fehlt.'),{code:'RELEASE_COMMIT_INVALID'});const files=[...entries].map(entry=>{const content=Buffer.isBuffer(entry.content)?entry.content:Buffer.from(entry.content);return{path:safePath(entry.path),size:content.length,mode:entry.mode===0o755?'0755':'0644',sha256:sha256(content)}}).sort((a,b)=>a.path.localeCompare(b.path,'en'));return{schemaVersion:1,format:'systemone-release-bundle',name,version,target,sourceCommit,sourceTimestamp:new Date(Number(sourceTimestamp)*1000).toISOString(),files}}
function createReleaseBundle(entries,metadata){const manifest=createManifest(entries,metadata),manifestBytes=Buffer.from(`${JSON.stringify(manifest,null,2)}\n`),archiveEntries=[...entries,{path:'RELEASE-MANIFEST.json',content:manifestBytes,mode:0o644}],tar=createTar(archiveEntries,{mtime:Number(metadata.sourceTimestamp)}),archive=zlib.gzipSync(tar,{level:9,mtime:0});return{archive,archiveSha256:sha256(archive),manifest}}
function verifyReleaseManifest(root,manifest){if(manifest?.schemaVersion!==1||manifest?.format!=='systemone-release-bundle'||manifest?.target!=='systemone-pi'||!/^[a-f0-9]{40}$/.test(String(manifest?.sourceCommit||''))||!Array.isArray(manifest?.files))throw Object.assign(new Error('Release-Manifest ist ungültig.'),{code:'RELEASE_MANIFEST_INVALID'});const seen=new Set();for(const file of manifest.files){const relative=safePath(file.path);if(seen.has(relative))throw Object.assign(new Error(`Doppelter Releasepfad: ${relative}`),{code:'RELEASE_FILE_DUPLICATE'});seen.add(relative);const absolute=path.join(root,relative),stat=fs.lstatSync(absolute);if(!stat.isFile()||stat.isSymbolicLink())throw Object.assign(new Error(`Releaseeintrag ist keine reguläre Datei: ${relative}`),{code:'RELEASE_FILE_INVALID'});const content=fs.readFileSync(absolute),mode=(stat.mode&0o111)?'0755':'0644';if(content.length!==file.size||sha256(content)!==file.sha256||mode!==file.mode)throw Object.assign(new Error(`Release-Datei weicht vom Manifest ab: ${relative}`),{code:'RELEASE_FILE_TAMPERED'})}return true}

module.exports={sha256,safePath,createTar,createManifest,createReleaseBundle,verifyReleaseManifest};
